846	function RuleCard({
847	  rule, projectId, isExpanded, onToggle, onEdit, onDuplicate, onDelete, isDuplicating, onUpdated,
848	  isNarrativeGrounded, isNarrativeEnhanced, onNarrativeEnhanced,
849	  ruleById, onRuleLinkClick,
850	  isDragging, dropIndicator, onDragStart, onDragOver, onDrop, onDragEnd,
851	}: {
852	  rule: Rule;
853	  projectId: number;
854	  isExpanded: boolean;
855	  onToggle: () => void;
856	  onEdit: () => void;
857	  onDuplicate: () => void;
858	  onDelete: () => void;
859	  isDuplicating: boolean;
860	  onUpdated: () => void;
861	  isNarrativeGrounded?: boolean;
862	  isNarrativeEnhanced?: boolean;
863	  onNarrativeEnhanced?: (ruleId: number) => void;
864	  ruleById: Map<number, Rule>;
865	  onRuleLinkClick: (id: number) => void;
866	  isDragging: boolean;
867	  dropIndicator: "before" | "after" | null;
868	  onDragStart: (e: React.DragEvent) => void;
869	  onDragOver: (e: React.DragEvent) => void;
