871	  onDragEnd: () => void;
872	}) {
873	  const queryClient = useQueryClient();
874	  const updateRule = useUpdateRule();
875	  const createRule = useCreateRule();
876	  const enhanceRule = useAiEnhanceRule();
877	  const { toast } = useToast();
878	
879	  const [showEnhance, setShowEnhance] = useState(false);
880	  const [isEnhancing, setIsEnhancing] = useState(false);
881	  const [enhance, setEnhance] = useState<AIEnhance | null>(null);
882	  const [applying, setApplying] = useState(false);
883	  const [applied, setApplied] = useState(false);
884	  const [addingIdx, setAddingIdx] = useState<number | null>(null);
885	
886	  const meta = catMeta(rule.category);
887	  const content = rule.content || "";
888	  const isLong = content.length > COLLAPSE_THRESHOLD;
889	  const display = !isExpanded && isLong ? content.slice(0, COLLAPSE_THRESHOLD).trimEnd() + "…" : content;
890	
891	  const errMsg = (err: unknown) => err instanceof Error ? err.message : String(err);
892	
893	  const handleEnhance = async () => {
894	    setIsEnhancing(true);
895	    setEnhance(null);
896	    setShowEnhance(true);
897	    try {
898	      const raw = await enhanceRule.mutateAsync({ projectId, ruleId: rule.id }) as Partial<AIEnhance> | null;
899	      const safeRelated = Array.isArray(raw?.relatedRuleSuggestions)
900	        ? raw!.relatedRuleSuggestions.filter((s): s is { title: string; content: string; category: string } =>
901	            !!s &&
902	            typeof s === "object" &&
903	            typeof s.title === "string" &&
904	            typeof s.content === "string",
905	          ).map((s) => ({
906	            title: s.title,
907	            content: s.content,
908	            category: typeof s.category === "string" ? s.category : "movement",
909	          }))
910	        : [];
911	      const data: AIEnhance = {
912	        rewrittenContent: typeof raw?.rewrittenContent === "string" ? raw.rewrittenContent : "",
913	        improvedTitle: typeof raw?.improvedTitle === "string" ? raw.improvedTitle : rule.title,
914	        designNotes: typeof raw?.designNotes === "string" ? raw.designNotes : undefined,
915	        edgeCases: typeof raw?.edgeCases === "string" ? raw.edgeCases : undefined,
916	        narrativeApplied: raw?.narrativeApplied === true,
917	        relatedRuleSuggestions: safeRelated,
918	      };
919	      if (!data.rewrittenContent) {
920	        toast({
921	          title: "AI returned no usable rewrite",
922	          description: "Try regenerating with a different model.",
923	          variant: "destructive",
924	        });
925	        setShowEnhance(false);
926	      } else {
927	        if (data.narrativeApplied) onNarrativeEnhanced?.(rule.id);
928	        setEnhance(data);
929	      }
930	    } catch {
931	      toast({
932	        title: "AI enhance failed",
933	        description: "Could not reach the server.",
934	        variant: "destructive",
935	      });
936	      setShowEnhance(false);
937	    } finally {
938	      setIsEnhancing(false);
939	    }
940	  };
941	
942	  const handleApply = async () => {
943	    if (!enhance) return;
944	    setApplying(true);
945	    try {
946	      await updateRule.mutateAsync({
947	        projectId,
948	        ruleId: rule.id,
949	        data: {
950	          title: enhance.improvedTitle || rule.title,
951	          content: enhance.rewrittenContent,
952	          ...(enhance.designNotes ? { designNotes: enhance.designNotes } : {}),
