999	      )}
1000	    <Card
1001	      className={`bg-card border-border overflow-hidden transition-all hover:shadow-md hover:shadow-black/20 group ${isDragging ? "opacity-40" : ""}`}
1002	      data-testid={`rule-card-${rule.id}`}
1003	    >
