1006	
1007	      <div className="px-4 pt-4 pb-2 flex items-start justify-between gap-3">
1008	        <div
1009	          draggable
1010	          onDragStart={onDragStart}
1011	          onDragEnd={onDragEnd}
1012	          className="flex items-center text-muted-foreground/60 hover:text-foreground cursor-grab active:cursor-grabbing self-stretch -ml-1 px-0.5 py-1 rounded hover:bg-card/80 transition-colors"
