171	                ) : (
172	                  <Button onClick={stopPlaythrough} variant="destructive" className="gap-2"><Square className="h-4 w-4" /> Stop</Button>
173	                )}
174	              </div>
175	              <div className="bg-muted/30 border border-border rounded-lg p-4 max-h-[500px] overflow-y-auto text-sm">
176	                {logs.length === 0 && !streaming && <div className="text-muted-foreground italic">No playthrough yet.</div>}
177	                {logs.map((l, i) => <div key={i} className="whitespace-pre-wrap">{l}</div>)}
178	                {streaming && <div className="text-primary animate-pulse mt-2">▍</div>}
179	              </div>
180	            </CardContent>
181	          </Card>
