242	  improvedTitle?: string;
243	  rewrittenContent?: string;
244	  designNotes?: string;
245	  edgeCases?: string;
246	  relatedRuleSuggestions?: Array<{ title?: string; content?: string; category?: string }>;
247	};
248	
249	type RuleRow = typeof rules.$inferSelect;
250	
251	function buildEnhanceRulePrompt(rule: RuleRow, existingTitles: string, narrativeLine: string): string {
252	  return `You are a senior board-game rules editor.${narrativeLine} Improve this rule and provide designer notes.
253	
254	Return ONLY a JSON object — no prose, no code fences. List the keys in EXACTLY this order so the most important fields are emitted first:
255	{
256	  "rewrittenContent": "1-4 sentences. Precise, unambiguous. May include 'Example:' on its own line. Keep under 600 characters.",
257	  "improvedTitle": "tightened title (<= 60 chars). If already good, repeat the original.",
258	  "designNotes": "1-2 sentences explaining the DESIGN INTENT — why this rule exists, what tension it creates, how it shapes player decisions. (<= 240 chars)",
259	  "edgeCases": "1-3 short bullet points (separated by ' • ') describing tricky cases, exceptions, or common rule-lawyering attempts. (<= 240 chars)",
260	  "relatedRuleSuggestions": [
261	    {
262	      "title": "title for a NEW related rule (<= 60 chars)",
263	      "content": "1-2 sentences (<= 200 chars)",
264	      "category": "movement | combat | economy | turn_structure | variant"
265	    }
266	  ]
267	}
268	
269	Suggest 1-3 related rules. Do NOT duplicate any of these existing rules:
270	${existingTitles}
271	
272	Current rule:
273	title: ${rule.title}
274	category: ${rule.category ?? "(none)"}
275	priority: ${rule.priority}
276	content: ${rule.content}
277	
278	Output JUST the JSON object. Keep total length under 1800 characters.`;
279	}
280	
281	function parseEnhanceRuleResult(text: string, rule: RuleRow) {
282	  const obj = tryParseJsonObject<EnhanceRuleAiResponse>(text);
283	  if (!obj?.rewrittenContent) return null;
284	  const relatedRuleSuggestions = (obj.relatedRuleSuggestions ?? [])
285	    .filter((s) => s?.title && s?.content)
286	    .map((s) => ({
287	      title: String(s.title),
288	      content: String(s.content),
289	      category: String(s.category ?? "movement"),
290	    }));
291	  return {
292	    improvedTitle: String(obj.improvedTitle ?? rule.title),
293	    rewrittenContent: String(obj.rewrittenContent),
294	    designNotes: obj.designNotes ? String(obj.designNotes) : undefined,
295	    edgeCases: obj.edgeCases ? String(obj.edgeCases) : undefined,
296	    relatedRuleSuggestions,
297	  };
298	}
