300	router.post(
301	  "/projects/:projectId/rules/:ruleId/enhance",
302	  async (req, res): Promise<void> => {
303	    const params = schemas.AiEnhanceRuleParams.safeParse(req.params);
304	    if (!params.success) {
305	      res.status(400).json({ error: params.error.message });
306	      return;
307	    }
308	    const [rule] = await db
309	      .select()
310	      .from(rules)
311	      .where(and(eq(rules.id, params.data.ruleId), eq(rules.projectId, params.data.projectId)));
312	    if (!rule) {
313	      res.status(404).json({ error: "Rule not found" });
314	      return;
315	    }
316	    const others = await db.select().from(rules).where(eq(rules.projectId, params.data.projectId));
317	    const existingTitles =
318	      others
319	        .filter((o) => o.id !== rule.id)
320	        .map((o) => `- ${o.title}`)
321	        .join("\n") || "(none)";
322	    const [project] = await db.select().from(projects).where(eq(projects.id, params.data.projectId));
323	    const narrativeLine = project?.narrative?.trim()
324	      ? `\nGame narrative: ${project.narrative.trim()}\n`
325	      : "";
326	    try {
327	      const text = await complete(req, {
328	        prompt: buildEnhanceRulePrompt(rule, existingTitles, narrativeLine),
329	        maxTokens: 3000,
330	      });
331	      const result = parseEnhanceRuleResult(text, rule);
332	      if (!result) {
333	        req.log.warn({ aiTextSnippet: text.slice(0, 500) }, "enhance rule: AI returned no usable fields");
334	        res.status(502).json({ error: "AI returned no usable content. Try again or switch model." });
335	        return;
336	      }
337	      res.json({ ...result, narrativeApplied: !!narrativeLine });
338	    } catch (err) {
339	      req.log.error({ err }, "enhance rule failed");
340	      res.status(500).json({ error: "Enhance failed" });
341	    }
342	  },
343	);
